<script setup>
import ManagementPage from '../../../Components/Inventory/ManagementPage.vue';
import { computed, ref } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';

defineOptions({layout:AdminLayout});
const props=defineProps({profile:{type:Object,required:true},urls:{type:Object,required:true}});
const showCurrent=ref(false),showNew=ref(false),showConfirm=ref(false);
const initials=computed(()=>(props.profile.name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join(''));
const changingPassword=computed(()=>Boolean(form.current_password||form.password||form.password_confirmation));
const passwordMatch=computed(()=>!form.password||form.password===form.password_confirmation);
const form=useForm({name:props.profile.name,email:props.profile.email,phone:props.profile.phone,current_password:'',password:'',password_confirmation:''});
function submit(){form.put(props.urls.update,{preserveScroll:true,onSuccess:()=>{form.current_password='';form.password='';form.password_confirmation=''}})}
</script>
<template>
    <ManagementPage mode="form">
<Head title="الملف الشخصي"/>
<PageHeader title="الملف الشخصي" icon="bi-person-circle" subtitle="بياناتك الشخصية وأمان حسابك — دون إعدادات إدارية"/>
<form class="profile-layout" @submit.prevent="submit">
 <aside class="profile-card"><div class="avatar-wrap"><img v-if="profile.avatar" :src="profile.avatar" :alt="profile.name"><span v-else>{{initials}}</span><i></i></div><h2>{{profile.name}}</h2><b><i class="bi bi-shield-check"></i>{{profile.role}}</b><dl><div><dt>اسم المستخدم</dt><dd>{{profile.username}}</dd></div><div v-if="profile.station"><dt>المحطة</dt><dd>{{profile.station}}</dd></div><div><dt>عضو منذ</dt><dd>{{profile.memberSince}}</dd></div></dl><div v-if="profile.branches.length" class="branches"><small>الفروع</small><span v-for="branch in profile.branches" :key="branch.id" :class="{primary:branch.primary}"><i class="bi bi-building"></i>{{branch.name}}<i v-if="branch.primary" class="bi bi-star-fill"></i></span></div></aside>
 <main><section class="form-card"><header><span><i class="bi bi-person-lines-fill"></i></span><div><h2>بيانات التواصل</h2><p>الاسم الذي يظهر للفريق ووسائل التواصل معك.</p></div></header><div class="fields"><label><span>الاسم الكامل *</span><input v-model="form.name" class="form-control" required autofocus><small v-if="form.errors.name">{{form.errors.name}}</small></label><label><span>البريد الإلكتروني</span><input v-model="form.email" class="form-control" type="email"><small v-if="form.errors.email">{{form.errors.email}}</small></label><label><span>رقم الجوال</span><input v-model="form.phone" class="form-control" inputmode="tel"><small v-if="form.errors.phone">{{form.errors.phone}}</small></label><label><span>اسم المستخدم</span><input :value="profile.username" class="form-control" disabled><em>تغييره يتم من إدارة المستخدمين.</em></label></div></section>
  <section class="form-card password"><header><span><i class="bi bi-shield-lock-fill"></i></span><div><h2>كلمة المرور</h2><p>اترك الحقول فارغة إن لم ترغب بتغييرها.</p></div></header><div class="security-note"><i class="bi bi-info-circle"></i>لحمايتك، يلزم إدخال كلمة المرور الحالية عند اختيار كلمة جديدة.</div><div class="fields"><label class="wide"><span>كلمة المرور الحالية</span><div class="password-input"><input v-model="form.current_password" class="form-control" :type="showCurrent?'text':'password'" autocomplete="current-password"><button type="button" @click="showCurrent=!showCurrent"><i class="bi" :class="showCurrent?'bi-eye-slash':'bi-eye'"></i></button></div><small v-if="form.errors.current_password">{{form.errors.current_password}}</small></label><label><span>كلمة مرور جديدة</span><div class="password-input"><input v-model="form.password" class="form-control" :type="showNew?'text':'password'" minlength="6" autocomplete="new-password"><button type="button" @click="showNew=!showNew"><i class="bi" :class="showNew?'bi-eye-slash':'bi-eye'"></i></button></div><em>6 أحرف على الأقل</em><small v-if="form.errors.password">{{form.errors.password}}</small></label><label><span>تأكيد كلمة المرور</span><div class="password-input"><input v-model="form.password_confirmation" class="form-control" :type="showConfirm?'text':'password'" autocomplete="new-password"><button type="button" @click="showConfirm=!showConfirm"><i class="bi" :class="showConfirm?'bi-eye-slash':'bi-eye'"></i></button></div><small v-if="form.password_confirmation&&!passwordMatch">كلمتا المرور غير متطابقتين</small></label></div></section>
  <footer><a :href="urls.dashboard" class="btn btn-light">إلغاء</a><button class="btn btn-primary" :disabled="form.processing||!passwordMatch||(changingPassword&&(!form.current_password||!form.password))"><i class="bi bi-check2-circle"></i>{{form.processing?'جارٍ الحفظ…':'حفظ التغييرات'}}</button></footer>
 </main>
</form>
    </ManagementPage>
</template>
